const esc=v=>String(v ?? "").replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));

export function safeUrl(value, image=false){
 const url=String(value ?? '').trim();
 if(!url || /[\\\x00-\x20]/.test(url)) return '';
 if(/^https?:\/\//i.test(url)) return url;
 if(!image && /^(#|mailto:|tel:)/i.test(url)) return url;
 if(/^(?:\.\/)?assets\//.test(url) && !url.split('/').includes('..')) return url.replace(/^\.\//,'');
 return '';
}
export function buttonHtml(b){const url=safeUrl(b?.url);return url && b?.label ? `<a class="text-link cms-button" href="${esc(url)}"${b.newTab?' target="_blank" rel="noopener noreferrer"':''}>${esc(b.label)}</a>`:''}
export function mediaHtml(item){const url=safeUrl(item?.image,true);return url ? `<figure class="cms-media"><img src="${esc(url)}" alt="${esc(item.imageAlt)}" loading="lazy">${item.caption?`<figcaption>${esc(item.caption)}</figcaption>`:''}</figure>`:''}

export function header(){return `<header class="site-header"><a class="brand" href="#top"><span>HXS</span><em>HUANG XUSHENG</em></a><button class="menu-toggle" aria-expanded="false">菜单</button><nav id="site-nav" class="site-nav"><a href="#top">首页</a><a href="#about">关于</a><a href="#research">研究</a><a href="#projects">项目</a><a href="#publications">成果</a><a href="#teaching">教学</a><a href="#talks">讲座</a><a href="#contact">联系</a></nav><span class="header-index">01 / 06</span></header>`}
export function hero(d,h={}){return `<section class="hero section-grid"><div class="hero-copy"><h1>${esc(d.name)}<span>${esc(d.english).replace(' ','<br> ')}</span></h1><p class="hero-intro">${esc(d.intro)}</p><div class="hero-meta"><span>${esc(d.unit)}</span><span>${esc(d.city)}</span></div>${buttonHtml(h.button)}</div><div class="hero-visual">${safeUrl(h.image,true)?`<img class="hero-photo" src="${esc(safeUrl(h.image,true))}" alt="${esc(h.imageAlt)}">`:""}${h.showCaption && h.caption?`<p class="cms-hero-caption">${esc(h.caption)}</p>`:""}</div></section>`}
export function about(d){return `<section id="about" class="about section-grid section-pad"><div class="section-label"><span></span><span>关于 ABOUT</span></div><div class="about-content"><p class="kicker">个人简介</p><h2>研究从空间细部出发，<br>回到公共生活。</h2><div class="about-columns">${d.bio.map(x=>`<p>${esc(x)}</p>`).join('')}</div>${buttonHtml({label:d.officialLabel,url:d.official,newTab:true})}</div></section>`}
export function research(items){return `<section id="research" class="research section-pad"><div class="section-head"><div class="section-label"><span></span><span>研究 RESEARCH</span></div><p class="section-note">以四个已确认研究方向组织成果，方便后续补充项目与图像。</p></div><div class="research-grid">${items.map((x,i)=>`<article class="${safeUrl(x.image,true)?'has-media':''}">${mediaHtml(x)}<span class="card-no">0${i+1}</span><h3>${esc(x.title).replace('与','<br>与')}</h3><p>${esc(x.description)}</p>${buttonHtml(x.button)}</article>`).join('')}</div></section>`}
export function projects(items){return `<section id="projects" class="projects section-pad"><div class="section-head"><div class="section-label"><span></span><span>精选项目 SELECTED PROJECTS</span></div><p class="section-note">项目图像、时间与完整名称待确认</p></div><div class="project-list">${items.map((x,i)=>`<article class="${safeUrl(x.image,true)?'has-media':''}">${mediaHtml(x)}<span>项目 PROJECT 0${i+1}</span><h3>${esc(x.title)}</h3><p>${esc(x.description)}</p>${buttonHtml(x.button)}<i>—</i></article>`).join('')}</div></section>`}
export function publications(items){const kind=x=>x==='journal'?'期刊论文':x==='conference'?'会议论文':'硕士论文'; return `<section id="publications" class="publications section-pad section-grid is-collapsed"><div class="section-label"><span></span><span>成果 PUBLICATIONS</span></div><div class="pub-content"><div class="pub-tabs"><button class="active" data-filter="all">全部 ${items.length}</button><button data-filter="journal">期刊论文 ${items.filter(x=>x.type==='journal').length}</button><button data-filter="conference">会议论文 ${items.filter(x=>x.type==='conference').length}</button><button data-filter="thesis">硕士论文 ${items.filter(x=>x.type==='thesis').length}</button></div><div id="pub-list" class="pub-list">${items.map(p=>`<article class="pub-row" data-kind="${esc(p.type)}"><span class="num">${esc(p.number)}</span><div>${mediaHtml(p)}<h3>${esc(p.title)}</h3><p class="pub-summary">${esc(p.venue)} · ${esc(p.year)}</p><p class="pub-full">${esc(p.authors)} · ${esc(p.venue)} · ${kind(p.type)} · DOI / 页码待确认</p>${buttonHtml(p.button)}</div><span class="year">${esc(p.year)}</span></article>`).join('')}</div><button class="more-toggle" data-target="publications">查看更多成果 ↗</button></div></section>`}
export function teaching(items){return `<section id="teaching" class="teaching section-pad is-collapsed"><div class="section-head"><div class="section-label"><span></span><span>教学 TEACHING</span></div><p class="section-note">课程名称与教学材料将按确认资料替换</p></div><div class="teaching-layout"><div class="course-list">${items.map(x=>`<article>${mediaHtml(x)}<span>${esc(x.category)}</span><h3>${esc(x.title)}</h3><p>${esc(x.description)}</p>${buttonHtml(x.button)}</article>`).join('')}</div><button class="more-toggle" data-target="teaching">查看更多教学 ↗</button></div></section>`}
export function talks(items){return `<section id="talks" class="talks section-pad is-collapsed"><div class="section-head"><div class="section-label"><span></span><span>讲座与动态 TALKS & NEWS</span></div><p class="section-note">讲座、奖项与活动信息待确认</p></div>${items.map(x=>`<div class="talk-grid"><div class="talk-date">${esc(x.date)}</div><div>${mediaHtml(x)}<h3>${esc(x.title)}</h3><p>${esc(x.description)}</p>${buttonHtml(x.button)}</div><span class="arrow">↗</span></div>`).join('')}<button class="more-toggle" data-target="talks">查看更多讲座 ↗</button></section>`}
export function contact(d){return `<section id="contact" class="contact section-pad"><div class="contact-inner"><p class="eyebrow">联系 CONTACT</p><h2>一起讨论<br>空间与城市。</h2><div class="contact-grid"><div><span>邮箱 EMAIL</span><a href="mailto:${esc(d.email)}">${esc(d.email)}</a></div><div><span>地址 ADDRESS</span><p>${esc(d.unit)}<br>${esc(d.city)}</p></div><div><span>链接 LINK</span>${buttonHtml({label:d.contactLabel,url:d.official,newTab:true})}</div></div></div></section>`}
export function footer(){return `<footer><span>© 2026 HUANG XUSHENG</span><span>ACADEMIC WEBSITE / V1.0</span><a href="#top">返回顶部 ↑</a></footer>`}
